`timescale 1ns / 1ps
// ============================================================================
// Self-checking testbench for dac_opt_sbox.v (generated by hdl/gen_verilog.py)
// ============================================================================
// Table: src.sbox_tables.TABLES['DAC-OPT'].  Checks every input against
// the forward and inverse tables, S^-1(S(x)) == x through a chained instance
// and the distinctness of the 32 outputs.  Prints a PASS/FAIL summary; any
// mismatch ends the simulation with $fatal (non-zero exit status).
// Run:  iverilog -g2012 -o sim dac_opt_sbox.v dac_opt_sbox_tb.v && vvp sim
// ============================================================================
module dac_opt_sbox_tb;

    reg  [4:0]  x;
    wire [4:0]  s_x;          // dac_opt_sbox(x)
    wire [4:0]  inv_x;        // dac_opt_sbox_inv(x)
    wire [4:0]  round_trip;   // dac_opt_sbox_inv(dac_opt_sbox(x))
    reg  [4:0]  expected_sbox [0:31];
    reg  [4:0]  expected_inv  [0:31];
    reg  [31:0] seen;
    integer i;
    integer errors_sbox, errors_inv, errors_round_trip, errors_bijective, errors;

    dac_opt_sbox     dut_sbox  (.data_in(x),   .data_out(s_x));
    dac_opt_sbox_inv dut_inv   (.data_in(x),   .data_out(inv_x));
    dac_opt_sbox_inv dut_chain (.data_in(s_x), .data_out(round_trip));

    initial begin
        // S(x) and S^-1(x), x = 0..31, from src.sbox_tables.TABLES['DAC-OPT']
        expected_sbox[0]  = 5'd2;  expected_sbox[1]  = 5'd8;  expected_sbox[2]  = 5'd19; expected_sbox[3]  = 5'd14;
        expected_sbox[4]  = 5'd7;  expected_sbox[5]  = 5'd10; expected_sbox[6]  = 5'd18; expected_sbox[7]  = 5'd0;
        expected_sbox[8]  = 5'd13; expected_sbox[9]  = 5'd21; expected_sbox[10] = 5'd17; expected_sbox[11] = 5'd16;
        expected_sbox[12] = 5'd28; expected_sbox[13] = 5'd26; expected_sbox[14] = 5'd6;  expected_sbox[15] = 5'd9;
        expected_sbox[16] = 5'd5;  expected_sbox[17] = 5'd30; expected_sbox[18] = 5'd24; expected_sbox[19] = 5'd22;
        expected_sbox[20] = 5'd3;  expected_sbox[21] = 5'd4;  expected_sbox[22] = 5'd12; expected_sbox[23] = 5'd29;
        expected_sbox[24] = 5'd23; expected_sbox[25] = 5'd31; expected_sbox[26] = 5'd20; expected_sbox[27] = 5'd1;
        expected_sbox[28] = 5'd11; expected_sbox[29] = 5'd27; expected_sbox[30] = 5'd15; expected_sbox[31] = 5'd25;
        expected_inv[0]  = 5'd7;  expected_inv[1]  = 5'd27; expected_inv[2]  = 5'd0;  expected_inv[3]  = 5'd20;
        expected_inv[4]  = 5'd21; expected_inv[5]  = 5'd16; expected_inv[6]  = 5'd14; expected_inv[7]  = 5'd4;
        expected_inv[8]  = 5'd1;  expected_inv[9]  = 5'd15; expected_inv[10] = 5'd5;  expected_inv[11] = 5'd28;
        expected_inv[12] = 5'd22; expected_inv[13] = 5'd8;  expected_inv[14] = 5'd3;  expected_inv[15] = 5'd30;
        expected_inv[16] = 5'd11; expected_inv[17] = 5'd10; expected_inv[18] = 5'd6;  expected_inv[19] = 5'd2;
        expected_inv[20] = 5'd26; expected_inv[21] = 5'd9;  expected_inv[22] = 5'd19; expected_inv[23] = 5'd24;
        expected_inv[24] = 5'd18; expected_inv[25] = 5'd31; expected_inv[26] = 5'd13; expected_inv[27] = 5'd29;
        expected_inv[28] = 5'd12; expected_inv[29] = 5'd23; expected_inv[30] = 5'd17; expected_inv[31] = 5'd25;

        errors_sbox = 0; errors_inv = 0; errors_round_trip = 0; errors_bijective = 0;
        seen = 32'd0;
        x = 5'd0;

        for (i = 0; i < 32; i = i + 1) begin
            x = i[4:0];
            #10;
            if (s_x !== expected_sbox[i]) begin
                errors_sbox = errors_sbox + 1;
                $display("  FAIL dac_opt_sbox(%0d) = %0d, expected %0d", i, s_x, expected_sbox[i]);
            end
            if (inv_x !== expected_inv[i]) begin
                errors_inv = errors_inv + 1;
                $display("  FAIL dac_opt_sbox_inv(%0d) = %0d, expected %0d", i, inv_x, expected_inv[i]);
            end
            if (round_trip !== x) begin
                errors_round_trip = errors_round_trip + 1;
                $display("  FAIL S^-1(S(%0d)) = %0d", i, round_trip);
            end
            seen = seen | (32'd1 << s_x);
        end
        if (seen !== 32'hFFFFFFFF) begin
            errors_bijective = 1;
            $display("  FAIL dac_opt_sbox outputs are not distinct (mask %h)", seen);
        end

        errors = errors_sbox + errors_inv + errors_round_trip + errors_bijective;
        $display("dac_opt_sbox_tb summary: sbox %0d/32, inverse %0d/32, S^-1(S(x)) %0d/32 mismatches",
                 errors_sbox, errors_inv, errors_round_trip);
        if (errors_bijective == 0)
            $display("dac_opt_sbox_tb bijectivity: PASS");
        else
            $display("dac_opt_sbox_tb bijectivity: FAIL");
        if (errors != 0) begin
            $display("dac_opt_sbox_tb: FAIL (%0d mismatches)", errors);
            $fatal(1, "dac_opt_sbox_tb failed");
        end
        $display("dac_opt_sbox_tb: PASS");
        $finish;
    end

endmodule
